AutoSwitchSettings
  /// The global DEFAULT threshold only (Settings → General, settings key autoSwitch.threshold).
  /// Never below 50: a 0% default would stop every account being used.
  static let thresholdRange = 50.0...100.0          // value unchanged; the Slider and SettingsCatalog keep using it
  static let accountThresholdRange = 0.0...100.0    // NEW: one account's own threshold; 0 = Manual only
  static let accountStepperRange = 1.0...100.0      // NEW: the Settings stepper; Manual only is chosen by name
  static let manualOnlyThreshold = 0.0              // NEW
  // clampedThreshold, defaultThreshold, fallbackThreshold: unchanged (50-100)
  static func normalizedAccountThreshold(_ value: Double?) -> Double? {
      guard let value, value.isFinite else { return nil }
      let whole = value.rounded()
      return whole <= accountThresholdRange.lowerBound ? accountThresholdRange.lowerBound : min(whole, accountThresholdRange.upperBound)
  }
  static func isManualOnly(own: Double?) -> Bool { normalizedAccountThreshold(own) == manualOnlyThreshold }
  // effectiveThreshold(own:defaultThreshold:): BODY UNCHANGED (normalizedAccountThreshold(own) ?? clampedThreshold(defaultThreshold)).
  //   It now returns 0 for Manual only.
  //   New doc: "the rule value auto-switch uses: own 0–100 when set (0 = Manual only), else the default 50–100".
  /// Where auto-switch moves the user OFF an account while it is active:
  /// the rule value, or the default for Manual only.
  static func leaveAtThreshold(rule: Double, defaultThreshold: Double) -> Double {
      rule > manualOnlyThreshold ? rule : clampedThreshold(defaultThreshold)
  }

AutoSwitchEngine
  static let hysteresis: Double = 10   // moved here from AppState.autoSwitchHysteresis, which is deleted
  /// The highest use at which an account may be switched TO: `room` under its own threshold,
  /// or half the threshold when that is smaller. nil for Manual only (0), a negative value or NaN.
  static func ceiling(threshold: Double, room: Double) -> Double? {
      guard threshold > AutoSwitchSettings.manualOnlyThreshold else { return nil }
      return threshold - min(room, threshold / 2)
  }

